mapper.select:
SELECT bl.*, u.user_name, u.avatar, bu.user_name as blackUserName, bu.avatar as blackUserAvatar FROM travel_black_list bl LEFT JOIN tb_user u ON bl.user_id = u.user_id LEFT JOIN tb_user bu ON bl.black_user_id = bu.user_id
and u.user_id = #{param.userId}
and bu.user_id = #{param.blackUserId}
and u.user_name like concat('%', #{param.userName} ,'%')
and bu.user_name like concat('%', #{param.blackUserName} ,'%')
order by bl.create_time desc
